import{Z as t,e as o,f as n,a0 as i}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Help Scout","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/help-scout.md","filePath":"integrations/help-desk/help-scout.md","lastUpdated":1780377007000}'),a={name:"integrations/help-desk/help-scout.md"};function r(s,e,l,h,c,p){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="help-scout" tabindex="-1">Help Scout <a class="header-anchor" href="#help-scout" aria-label="Permalink to &quot;Help Scout&quot;">​</a></h1><p>Connect Help Scout to send support enquiries to your help-desk account. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Help Scout</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-help-scout-api" tabindex="-1">Step 2. Connect to the Help Scout API <a class="header-anchor" href="#step-2-connect-to-the-help-scout-api" aria-label="Permalink to &quot;Step 2. Connect to the Help Scout API&quot;">​</a></h3><ol><li>Go to <a href="https://secure.helpscout.net/" target="_blank">Help Scout</a> and log into your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Your Profile</strong>.</li><li>In the left-hand menu, click <strong>My Apps</strong>.</li><li>Click the <strong>Create My App</strong> button.</li><li>Provide an app name (e.g. <code>Formie</code>).</li><li>In the <strong>Redirection URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>App ID</strong> from Help Scout and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>App Secret</strong> from Help Scout and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination options offered by this integration and map required fields with the variable picker. For a support enquiry, map the visitor’s email and message where those fields are available.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the resulting enquiry in the selected account and check the sender details and submitted message.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=t(a,[["render",r]]);export{g as __pageData,u as default};
